export function validateGLB(bytes){const v=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);if(bytes.length<20||v.getUint32(0,true)!==0x46546c67||v.getUint32(4,true)!==2||v.getUint32(8,true)!==bytes.length||v.getUint32(16,true)!==0x4e4f534a)throw new Error('Upload a valid GLB 2.0 file.');const n=v.getUint32(12,true);if(n>bytes.length-20)throw new Error('Invalid GLB JSON chunk.');const d=JSON.parse(new TextDecoder().decode(bytes.subarray(20,20+n)));if((d.extensionsRequired||[]).some(x=>['KHR_draco_mesh_compression','EXT_meshopt_compression','KHR_texture_basisu'].includes(x)))throw new Error('Export a GLB without Draco, Meshopt, or KTX2 compression for this viewer.');if(!d.meshes?.length)throw new Error('This GLB contains no meshes.');for(const a of [...(d.buffers||[]),...(d.images||[])])if(a.uri&&!a.uri.startsWith('data:'))throw new Error('Use a self-contained GLB with embedded textures.');return d;}
export function validateMetadata(d){if(!d||typeof d!=='object')throw new Error('Invalid project settings.');let tasks=d.tasks||[];if(!Array.isArray(tasks)||tasks.length>500)throw new Error('Use at most 500 tasks.');const ids=new Set();tasks=tasks.map(t=>{const id=String(t.id||'').trim();if(!id||id.length>100||ids.has(id))throw new Error('Task IDs must be unique.');ids.add(id);const start=Number(t.start),duration=Number(t.duration);if(!Number.isFinite(start)||!Number.isFinite(duration)||start<0||duration<=0||start+duration>100000)throw new Error('Each task needs a nonnegative start and positive duration in days.');return {id,name:String(t.name||id).slice(0,180),start,duration};});
const mappings={};for(const [key,value]of Object.entries(d.mappings||{})){if(!/^mesh_\d+$/.test(key)||!ids.has(value))throw new Error('A component link refers to an unknown task.');mappings[key]=value;}
const a=d.alignment||{};const bound=(n,f,min,max)=>{n=Number(n??f);if(!Number.isFinite(n)||n<min||n>max)throw new Error('Alignment is outside its allowed range.');return n;};
return {tasks,mappings,stadiumScheduleLinked:d.stadiumScheduleLinked===true,alignment:{width:bound(a.width,.7,.05,2),x:bound(a.x,0,-1,1),y:bound(a.y,0,-1,1),rotation:bound(a.rotation,0,-180,180)},description:String(d.description||'').slice(0,1000)};}
